insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p142', 'allemand', '3AS', 16, 142, 'L7 3AS p142 — Problemliste Nicole/Alexander + Antworten zum Rundfunkinterview', E'4. Über welche Probleme sprechen Nicole und Alexander ? Bilden Sie richtige Sätze.\nProblemliste : Nicole (6 lignes) · Alexander (6 lignes)\n5. Antworten Sie.\n1. Wen interviewt der Moderator ?\n2. Warum möchte Nicole in den Medien arbeiten ?\n3. Was ist wichtig für Alexander ?\n4. Worum ist Nicole besorgt ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p143', 'allemand', '3AS', 16, 143, 'L7 3AS p143 — Konjunktiv II Vergangenheit (wäre/hätte + Partizip II) + Konditionalsätze', E'Wenn das Wörtchen «wenn» nicht gewesen wäre…\n1. Lesen Sie und variieren Sie.\nWenn ich zu Hause geblieben wäre, wäre der Unfall nicht passiert.\nKonjunktiv II Vergangenheit : wäre/ hätte … + Partizip II\nTabelle : zu Hause bleiben · zu spät kommen · pünktlich sein · einen Mantel anziehen · nicht krank sein · der Unfall/nicht passieren · die Sendung verpassen · meine Oma treffen · sich nicht erkälten · die Arbeit erledigen\n2. Was hätten Ihre Eltern gemacht, wenn sie Journalisten gewesen wären ?\n- Die Bürger objektiver informieren.\n- Mehr Artikel über Jugendprobleme schreiben.\n- Die Wahrheit immer sagen.\n- Die Umweltverschmutzung kritisieren.\n- Auch über Tabuthemen berichten.\n- Interessante Reportagen machen.\n3. Bilden Sie Konditionalsätze.\n- Du hast nicht auf mich gehört. Du bist unvernünftig gewesen.\n- Unser Lehrer hat uns nicht unterstützt. Wir haben es nicht geschafft.\n- Dieser Mann war nicht berufstätig. Sein Vater hat ihm lange geholfen.\n- Peter war nicht berufstätig. Sein Vater musste ihn unterstützen.\n- Nicole hat Medizin studiert. Ihre Eltern haben ihr Studium finanziert.\n- Ich wusste seine Telefonnummer nicht. Ich konnte ihn nicht anrufen.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p144', 'allemand', '3AS', 16, 144, 'L7 3AS p144 — Wiederholung Zum Sprechen : Träume (Ida/Katharina/Peter/Oliver)', E'Wiederholung — Zum Sprechen\n1. «Träume und Gedanken kennen keine Schranken», sagt ein Sprichwort. Was träumen Leute von heute ?\nIda : Ich wünsche mir den Frieden für die Welt. Ich persönlich träume von Glück und Erfolg in meinem Leben.\nKatharina : Mein größter Traum ist, immer unabhängig und frei zu sein. Unabhängig im Job. Ich möchte die Möglichkeit haben, raus zu können. Ich möchte reisen, wenn ich Lust dazu habe. Und dort leben, wo es mir gefällt.\nPeter : Mein größter Wunsch ist es, mein Psychologiestudium gut zu beenden. Dann wünsche ich mir ein Haus und viel Geld.\nOliver : Auf den Mond fliegen : Das ist mein größter Traum.\n2. Und Sie, was ist Ihr großer Traum ? Erzählen Sie kurz davon.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p145', 'allemand', '3AS', 16, 145, 'L7 3AS p145 — Haben Sie Probleme ? 4 Cartoons (Stress/Clique/Eltern)', E'3. Haben Sie Probleme ? Reden Sie darüber. Reden Sie mit einem guten Freund oder mit Ihren Eltern. Reden hilft.\n4 Cartoons :\n- Der Stress in der Schule ist zuviel für mich. (Mathe · Deutsch · Englisch · Chemie · Bio)\n- In unserer Clique bin ich immer das fünfte Rad am Wagen.\n- Was meine Eltern verlangen, kann ich nicht. (Zeugnis)\n- Meine Eltern verstehen mich nicht.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p146', 'allemand', '3AS', 16, 146, 'L7 3AS p146 — Zum Lesen : Die Jugend (Sokrates-Zitat) + R/F + Fragen', E'Zum Lesen\n1. Lesen Sie den Text.\nDie Jugend\n«Die Jugend liebt heute den Luxus. Sie hat schlechte Manieren, verachtet die Autorität, hat keinen Respekt mehr vor älteren Leuten und diskutiert, wenn sie arbeiten sollte. Die Jugendlichen stehen nicht mehr auf, wenn Ältere das Zimmer betreten. Sie verschlingen bei Tisch die Speisen und legen die Beine übereinander. Sie widersprechen ihren Eltern und tyrannisieren ihre Lehrer.»\nDieser Ausspruch stammt nicht von einem Erwachsenen des 21. Jahrhunderts, wie man annehmen könnte, sondern von Sokrates, dem berühmten Philosophen, der bereits 399 vor Chr. gestorben ist.\nIn die Jugend fallen die Pubertät, die Schulbildung, die Berufsausbildung und die Identitätsfindung… Man kann also annehmen, dass es zu jeder Zeit Konflikte zwischen den Generationen gegeben hat.\nTrotzdem hat jede Jugend auch ihre eigenen Probleme.\n2. Richtig oder falsch ? Kreuzen Sie an. (R/F)\n- Die Jugend hat das bequeme Leben gern.\n- Die Jugend respektiert die Alten.\n- Die Jugendlichen haben gute Beziehungen zu ihren Lehrern.\n- Früher hat es keine Generationskonflikte gegeben.\n3. Beantworten Sie die Fragen.\n1. Was war Sokrates ?\n2. Wie verhält sich die Jugend heute ?\n3. Warum hat es immer Generationskonflikte gegeben ?\n4. Überlegen Sie : Hatte die Jugend früher die gleichen Probleme wie heute ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
